%[text] ## Local Helper Functions
%[text] If you wish to see the code details, on the MATLAB toolstrip select **View** \> **Output Inline**. Alternatively, select **Output Inline** using the icon ![Live script output inline icon](text:image:163f) at the top right of the Live Editor pane.
function checkAnswer(questionID,userAnswer)

% Primary correct answers
keys = struct;
keys.Q1 = [1,1,0];
keys.Q2 = "Degree 5";
keys.Q3 = "To learn the relationship between inputs and a continuous output";

% Hints
hints = struct;
hints.Q1 = "Think about which models can capture nonlinearity and which cannot.";
hints.Q2 = "Try increasing polynomial degree until the curve fits the oscillations.";
hints.Q3 = "Consider what regression aims to estimate for continuous targets.";

% Input validation
if nargin < 2
    warning("Select a valid option");
    return
end

if (isstring(userAnswer) || ischar(userAnswer)) && strcmpi(strtrim(userAnswer),"Select")
    warning("Select a valid option");
    return
end

% Special validation for Q1
if strcmp(questionID,"Q1") && isequal(userAnswer,[0,0,0])
    warning("Select a valid option");
    return
end

% Check answer
if isfield(keys,questionID)

    correct = keys.(questionID);

    if isstring(correct) || ischar(correct)
        isCorrect = strcmpi(strtrim(string(userAnswer)),strtrim(string(correct)));
    else
        isCorrect = isequal(userAnswer,correct);
    end

    if isCorrect
        disp("You are correct!");
    else
        disp("Not quite. Try again.");

        if isfield(hints,questionID)
            disp("Hint: " + hints.(questionID));
        end
    end

else
    warning("Unknown question ID.");
end

end
%%
function [xChirp,yChirp] = OscillData
rng shuffle
% Oscillatory frequency that changes with x (chirp) 
xChirp = linspace(0,24,150)'; % more points to show oscillation

% Base chirp (sin(x^2)) on a normalized domain, then scale to look like your prior range.
xNorm  = linspace(0,6*pi,numel(xChirp))'; % drives the changing frequency
yChirpRaw = sin(xNorm.^2); % oscillatory frequency increases with x

% Scale/shift to be comparable to your earlier amplitude/offset (~50 center)
centerA = 50;
ampA = 12;
noiseA  = 0.5; % modest noise (homoscedastic here)
yChirp = centerA + ampA*yChirpRaw + noiseA*randn(size(yChirpRaw));
end
%%
function [xHet,yHet] = HeteroData
rng shuffle
% Nonstationary variance + nonlinear mean
xHet = linspace(0,1,220)'; % keep it [0,1] for a simple sigma(x)
meanB = 50 + 12*sin(2*pi*xHet) + 6*sin(6*pi*xHet); % nonlinear mean (mixed freqs)
sigmaB = 2 + 10*xHet; % variance grows with x (heteroscedastic)
yHet  = meanB + sigmaB.*randn(size(xHet));
end
%%
function [xUknwn,yUknwn] = Unknown
% Create a simple linear function dataset
xUknwn = linspace(0,10,50)'; % predictor
slope = 3.2;
intercept = -1.5;
noiseStd = 0.5;
yUknwn = slope*xUknwn + intercept + noiseStd*randn(size(xUknwn));
end
%%
function [axFit,axQQ] = ResidualsPlots(mdl,parentLayout,tileIdxFit,tileIdxQQ,label)
axFit = nexttile(parentLayout,tileIdxFit);
axQQ  = nexttile(parentLayout,tileIdxQQ);

yhat = mdl.Fitted;
res  = mdl.Residuals.Raw;

% Residuals vs Fitted
scatter(axFit,yhat,res,20,"filled",MarkerFaceAlpha=0.6)
yline(axFit,0,LineWidth=1.2)

grid(axFit,"on")
box(axFit,"on")
xlabel(axFit,"Fitted Values",Interpreter="latex")
ylabel(axFit,"Residuals",Interpreter="latex")
title(axFit,"Residuals: "+label,Interpreter="latex")

% QQ plot
resStd = (res-mean(res))./std(res);

n = numel(resStd);
p = ((1:n)'-0.5)/n;
q = sqrt(2)*erfinv(2*p-1);

resSorted = sort(resStd);

scatter(axQQ,q,resSorted,20,"filled",MarkerFaceAlpha=0.6,SeriesIndex=5)
hold(axQQ,"on")

coeffs = polyfit(resSorted,q,1);
plot(axQQ,q,polyval(coeffs,q),LineWidth=1.2,SeriesIndex="none")

grid(axQQ,"on")
box(axQQ,"on")
xlabel(axQQ,"Normal Quantiles",Interpreter="latex")
ylabel(axQQ,"Standardized Residuals",Interpreter="latex")
title(axQQ,"Normality: "+label,Interpreter="latex")

end
%%
function PlotTransClean(x,y,xFeat)

% Build tables
T0 = table(x,y);

if isvector(xFeat)
    T1 = table(xFeat,y,VariableNames={'f1','y'});
    formulaFeat = 'y ~ f1';
else
    T1 = array2table(xFeat);
    T1.y = y;

    vars = T1.Properties.VariableNames;
    vars(strcmp(vars,'y')) = [];
    formulaFeat = "y ~ " + strjoin(vars,' + ');
end

% Fit models
mdl0 = fitlm(T0,"y ~ x");
mdl1 = fitlm(T1,formulaFeat);

yhat0 = mdl0.Fitted;
yhat1 = mdl1.Fitted;

% Plot layout
figure
g.Units = "normalized";
g.OuterPosition = [0 0 0.5 0.5]; %#ok<*STRNU>
t = tiledlayout(2,3,TileSpacing="compact",Padding="compact");
sgtitle("Feature Transformation Diagnostics",Interpreter="latex")

% Original space
nexttile(t,1)
scatter(x,y,20,"filled",SeriesIndex=3)
hold on
plot(x,yhat0,LineWidth=2,SeriesIndex=6)
title("Original Space (Misspecified)",Interpreter="latex")
xlabel("x",Interpreter="latex")
ylabel("y",Interpreter="latex")
grid on
box on

% Residuals + QQ (no feature)
ResidualsPlots(mdl0,t,2,3,"No Feature");

% Feature space
nexttile(t,4)
scatter(yhat1,y,20,"filled",SeriesIndex=3)
hold on
plot(yhat1,yhat1,LineWidth=2,SeriesIndex=6)
title("Feature Model (Closer to Linear)",Interpreter="latex")
xlabel("Predicted",Interpreter="latex")
ylabel("Observed",Interpreter="latex")
grid on
box on

% Residuals + QQ (feature)
ResidualsPlots(mdl1,t,5,6,"With Feature");

% ANOVA output
disp("The ANOVA for the raw model is:")
anova(mdl0)

disp("The ANOVA for the feature transformed model is:")
anova(mdl1)

end
%%
function plotDataByAxis(AX,xPl,yPl,SpecialFunc)

% Layout
scr = get(groot,"Screensize");
f = figure(Units="pixels",Position=scr,NumberTitle="off",Name="Data Explorer",Color=[1 1 1],WindowState="maximized");
t = tiledlayout(f,2,2,TileSpacing="compact",Padding="compact");

axMain = nexttile(t,[1 2]);


% Defaults

xFit = xPl;
yFit = yPl;
plotFcn = @(ax,x,y) scatter(ax,x,y,20,"filled",SeriesIndex=3,MarkerFaceAlpha=0.7);
xlab = "x";
ylab = "y";
ttl  = "Standard x-y Plot";
valid = true(size(xPl));


% Behavior switch

switch AX

    case "Select"
        warning("Select a valid option.")
        return

    case "x-y"
        % default

    case "semi-logy"
        plotFcn = @(ax,x,y) scatter(ax,x,y,20,"filled",SeriesIndex=3,MarkerFaceAlpha=0.7);

        ylab = "$\ln(y)$";
        ttl  = SpecialFunc + " on Semi-log Plot for Exponential Model";

        valid = yPl>0;
        xFit = xPl(valid);
        yFit = log(yPl(valid));

    case "log-log"
        plotFcn = @(ax,x,y) scatter(ax,x,y,20,"filled",SeriesIndex=3,MarkerFaceAlpha=0.7);

        xlab = "$\ln(x)$";
        ylab = "$\ln(y)$";
        ttl  = SpecialFunc + " on Log-Log Plot for Power Law Model";

        valid = (xPl>0)&(yPl>0);
        xFit = log(xPl(valid));
        yFit = log(yPl(valid));

    case "saturation"
        plotFcn = @(ax,x,y) scatter(ax,1./x,1./y,20,"filled",SeriesIndex=3,MarkerFaceAlpha=0.7);

        xlab = "$1/x$";
        ylab = "$1/y$";
        ttl  = SpecialFunc + " on Reciprocal Plot for Saturation Model";

        valid = (xPl~=0)&(yPl~=0);
        xFit = 1./xPl(valid);
        yFit = 1./yPl(valid);

    case "sigmoidal(S-Curve)"

        yNorm = (yPl-min(yPl))/(max(yPl)-min(yPl));
        valid = (yNorm>0)&(yNorm<1);

        plotFcn = @(ax,x,y) scatter(ax,x,log(1./y),20,"filled",SeriesIndex=3,MarkerFaceAlpha=0.7);

        xlab = "$x$";
        ylab = "$\ln(1/y)$";
        ttl  = SpecialFunc + " on Transformed Plot for Sigmoidal Model";

        xFit = xPl(valid);
        yFit = log(yNorm(valid)./(1 - yNorm(valid)));
      

    otherwise
        warning("Unknown AX option: %s",AX)
        return
end


% Main plot

plotFcn(axMain,xPl(valid),yPl(valid))
xlabel(axMain,xlab,Interpreter="latex")
ylabel(axMain,ylab,Interpreter="latex")
title(axMain,ttl,Interpreter="latex")
grid(axMain,"on")
box(axMain,"on")
axis(axMain,"padded")


% Special ticks (semi-logy only)
if AX=="semi-logy"
    yl = ylim(axMain);
    k = floor(log(yl(1))):ceil(log(yl(2)));
    yticks(axMain,exp(k));
    yticklabels(axMain,compose("e^{%d}",k));
end


% Fit model
mdl = fitlm(xFit,yFit);


% Residual diagnostics (reusable)

ResidualsPlots(mdl,t,3,4,"Transformed");

end

